SELECT 'gongkao', '两集合容斥', 'kp-xingce-quantity-math-operation-inclusion-exclusion-two-sets', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "两集合容斥"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "总数 = A + B - 都满足 + 都不满足。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "只涉及两个属性的交叉。如“英语”、“法语”；“及格”、“不及格”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、公式变形推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "根据题目给出的不同条件，公式可以灵活变异："}]}, {"type": "katexBlock", "attrs": {"content": "\\text{总数} = \\text{只满足A} + \\text{只满足B} + \\text{都满足} + \\text{都不满足}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "注意：A = 只满足A + 都满足。这是新手最容易搞混的概念！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目提取 A, B, 都不, 都满足, 总数 5 个元素] --> B[必然已知其中 4 个, 设未知为 x]\nB --> C[列一元一次方程: 总数 = A + B - 都满足 + 都不满足]\nC --> D[解出 x]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 某公司 100 人。会英语 60 人，会法语 50 人，只会英语 40 人。求两样都不会的几人？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "陷阱识别：题目给了“只会英语 40 人”。而公式里需要的是“都会的人”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "推导都会：都会 = 会英语(60) - 只会英语(40) = 20 人。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "套公式：100 = 会英语(60) + 会法语(50) - 都会(20) + 都不会(x)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "解方程：100 = 90 + x。x = 10。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“会A”与“只会A”混为一谈：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "会英语（A）包含了两部分人：只会英语的人，以及既会英语又会法语的人。当题目说“只会英语”时，它已经是被剔除了交集的纯粹个体，不能直接代入 A+B-AB 的公式里当 A 用！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "做两集合题目，在草稿纸上画两个相交的圆。把数字填进圆里，比背公式直观一万倍。"}]}]}$$ AS jsonb), NULL, '两集合容斥的核心考点与实战推导。', category_node.id, CAST('["数量关系", "容斥问题", "两集合容斥"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_inclusion_exclusion_two_sets", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
